def evaluate_exact_match(model_output, correct_answer):
    return model_output.strip().lower() == correct_answer.lower()

outputs = [
    get_completion(
        f"Classify this as 'positive', 'negative', 'neutral', or 'mixed'. "
        f"Output only the label: {t['text']}"
    )
    for t in tweets  # includes sarcasm and mixed-sentiment edge cases
]
accuracy = sum(
    evaluate_exact_match(o, t["sentiment"]) for o, t in zip(outputs, tweets)
) / len(tweets)

def chunk_text(text, chunk_size=20000):
    return [text[i:i + chunk_size] for i in range(0, len(text), chunk_size)]

def summarize_long_document(text, details_to_extract, model, max_tokens):
    chunk_summaries = [
        summarize_document(c, details_to_extract, model=model, max_tokens=max_tokens)
        for c in chunk_text(text)
    ]
    # Final pass combines the chunk summaries into one coherent summary
    return summarize_document("".join(chunk_summaries), details_to_extract,
                              model=model, max_tokens=max_tokens)
